mapper.select:
SELECT *
FROM uav_detect_msg
WHERE station_id = #{stationId}
  AND data_time BETWEEN #{startTime} AND #{endTime}
ORDER BY data_time DESC
    LIMIT #{offset}, #{pageSize}

SELECT t1.model, t1.serial, t1.station_id, t1.data_time, IFNULL(config.name, '') AS station_name, IFNULL(t2.brand, '未知') AS brand, IFNULL(t2.`status`, 3) AS status, IFNULL(t2.auth_status, 3) AS auth_status FROM ( -- 窗口函数仅扫描索引，无需全表+排序 SELECT REPLACE(model, ' ', '') AS model, serial, station_id, data_time, ROW_NUMBER() OVER (PARTITION BY serial ORDER BY data_time DESC) AS rn FROM uav_detect_msg
-- 1. 优化StationId条件：简化嵌套IF，逻辑更清晰
station_id = #{StationId}
-- 2. 优化日期条件：用范围查询替代函数，触发索引
AND data_time >= CONCAT(#{rq},' 00:00:00') AND data_time <= CONCAT(#{rq},' 23:59:59')
) t1 LEFT JOIN wjbd_wrj_jbxx t2 ON t1.serial = t2.serial_number LEFT JOIN uav_device_config config ON t1.station_id = config.station_id WHERE t1.rn = 1
and t2.auth_status = #{authStatus}
ORDER BY t1.data_time DESC

SELECT t.*, CASE WHEN ROUND( -- 速度权重0.4（sd为m/s，无需转换） 0.4 * IF(sd IS NULL, 0, 1 - EXP(-0.005 * (LEAST(GREATEST(sd, 0), 150))) ) + -- 距离权重0.3（distance从km转米后计算） 0.3 *IF(distance IS NULL, 1, 1 / (1 + EXP(0.02 * (LEAST(GREATEST(distance , -100), 1000) - 30)))
) + -- 高度权重0.3（height/altitude为米） 0.3 * IF(IFNULL(height, altitude) IS NULL, 1, 1 / (1 + EXP(2 * POWER(10, -8) * POWER(LEAST(GREATEST(IFNULL(height, altitude), 0), 10000) - 1000, 2))) ), 4 ) >= 0.7 THEN 'red' WHEN ROUND( -- 速度权重0.4（sd为m/s，无需转换） 0.4 * IF(sd IS NULL, 0, 1 - EXP(-0.005 * (LEAST(GREATEST(sd, 0), 150))) ) + -- 距离权重0.3（distance从km转米后计算） 0.3 *IF(distance IS NULL, 1, 1 / (1 + EXP(0.02 * (LEAST(GREATEST(distance , -100), 1000) - 30)))
) + -- 高度权重0.3（height/altitude为米） 0.3 * IF(IFNULL(height, altitude) IS NULL, 1, 1 / (1 + EXP(2 * POWER(10, -8) * POWER(LEAST(GREATEST(IFNULL(height, altitude), 0), 10000) - 1000, 2))) ), 4 ) >= 0.4 THEN 'yellow' ELSE 'green' END AS wxdj FROM ( SELECT -- 替换子查询+GROUP BY为窗口函数，一次扫描完成 u.*, ROW_NUMBER() OVER (PARTITION BY model_clean, serial_clean ORDER BY data_time DESC) AS rn FROM uav_detect_msg u WHERE dron_lng IS NOT NULL AND dron_lng != 0
AND data_time >= CONCAT(#{rq},' 00:00:00') AND data_time <= CONCAT(#{rq},' 23:59:59')
AND (model_clean, serial_clean) IN (
(#{item.modelClean}, #{item.serialClean})
) ) t WHERE t.rn = 1 -- 仅保留每个(model_clean+serial_clean)的最新记录 ORDER BY t.data_time DESC

SELECT t1.*
from wjbd_wrj_jbxx t2  right join  uav_detect_msg t1 on t1.serial = t2.serial_number and t1.model = t2.model



        and year(t1.data_time) = #{nf}


        and MONTH(t1.data_time) = #{yf}


        and ifnull(t2.brand,'未知')  = #{brand}


        and t1.model = #{model}


        and t1.serial = #{serial}


ORDER BY data_time desc

select DATE (data_time) as rq, '无人机飞行' as type
from uav_detect_msg


        year(data_time) = #{nf}


        and MONTH(data_time) = #{yf}


GROUP BY DATE (data_time)
ORDER BY data_time desc
